// Conditional proc macro inclusion
macro_rules! proc_macro_item {
    ($($item:tt)*) => {
        #[cfg(feature = "proc_macros")]
        $($item)*
    };
}

macro_rules! no_proc_macro_item {
    ($($item:tt)*) => {
        #[cfg(not(feature = "proc_macros"))]
        $($item)*
    };
}

